import urllib.request
import urllib.error
import json
import base64

MCP_URL = "http://loophole-sim:8000/mcp"

class LoopholeClient:
    def __init__(self, url=MCP_URL):
        self.url = url
        self.req_id = 0
        self.session_id = None
        self._initialize()

    def _rpc(self, method, params=None):
        self.req_id += 1
        headers = {
            "Content-Type": "application/json",
            "Accept": "application/json"
        }
        if self.session_id:
            headers["Mcp-Session-Id"] = self.session_id
        data = {
            "jsonrpc": "2.0",
            "id": self.req_id,
            "method": method
        }
        if params is not None:
            data["params"] = params
        req = urllib.request.Request(
            self.url,
            method="POST",
            data=json.dumps(data).encode("utf-8"),
            headers=headers
        )
        with urllib.request.urlopen(req, timeout=30) as resp:
            sess = resp.headers.get("Mcp-Session-Id")
            if sess:
                self.session_id = sess
            body = json.loads(resp.read().decode("utf-8"))
            if "error" in body:
                raise RuntimeError(f"RPC Error: {body['error']}")
            return body.get("result")

    def _initialize(self):
        self._rpc("initialize", {
            "protocolVersion": "2024-11-05",
            "capabilities": {},
            "clientInfo": {"name": "python-solver", "version": "1.0"}
        })
        try:
            self._rpc("notifications/initialized")
        except Exception:
            pass

    def call_tool(self, name, arguments=None):
        if arguments is None:
            arguments = {}
        res = self._rpc("tools/call", {
            "name": name,
            "arguments": arguments
        })
        if res.get("isError"):
            raise RuntimeError(f"Tool error: {res}")
        content = res.get("content", [])
        return content

    def get_state(self):
        c = self.call_tool("get_state")
        return json.loads(c[0]["text"])

    def get_contacts(self):
        c = self.call_tool("get_contacts")
        return json.loads(c[0]["text"])

    def render(self, view=None, azimuth=None, elevation=None, distance=None, lookat=None, modalities=None, width=480, height=360):
        args = {"width": width, "height": height}
        if view: args["view"] = view
        if azimuth is not None: args["azimuth"] = azimuth
        if elevation is not None: args["elevation"] = elevation
        if distance is not None: args["distance"] = distance
        if lookat is not None: args["lookat"] = lookat
        if modalities: args["modalities"] = modalities
        return self.call_tool("render", args)

    def grab(self, handle=0, target="tube_b", point=None):
        args = {"handle": handle, "target": target}
        if point is not None: args["point"] = point
        c = self.call_tool("grab", args)
        return json.loads(c[0]["text"])

    def move(self, handle=0, dx=0.0, dy=0.0, dz=0.0, droll=0.0, dpitch=0.0, dyaw=0.0, frame="world"):
        args = {
            "handle": handle,
            "dx": dx, "dy": dy, "dz": dz,
            "droll": droll, "dpitch": dpitch, "dyaw": dyaw,
            "frame": frame
        }
        c = self.call_tool("move", args)
        return json.loads(c[0]["text"])

    def release(self, handle=0):
        c = self.call_tool("release", {"handle": handle})
        return json.loads(c[0]["text"])

    def wait(self, steps=100):
        c = self.call_tool("wait", {"steps": steps})
        return json.loads(c[0]["text"])

if __name__ == "__main__":
    client = LoopholeClient()
    state = client.get_state()
    print("Puzzle:", state.get("puzzle"))
    print("Actions used:", state.get("actions_used"), "Remaining:", state.get("actions_remaining"))
    print("Objects:", state.get("objects"))
    print("Handles:", state.get("handles"))
    print("Limits:", state.get("limits"))
    contacts = client.get_contacts()
    print("Contacts:", contacts)

