#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <fstream>
#include <unordered_map>

struct Point {
    float x, y, z;
};

// Spatial hash grid for fast collision checking
struct HashKey {
    int i, j, k;
    bool operator==(const HashKey& o) const {
        return i == o.i && j == o.j && k == o.k;
    }
};

struct HashKeyHasher {
    std::size_t operator()(const HashKey& k) const {
        return ((std::hash<int>()(k.i) ^ (std::hash<int>()(k.j) << 1)) >> 1) ^ (std::hash<int>()(k.k) << 1);
    }
};

class VoxelCollisionChecker {
public:
    float cellSize;
    std::unordered_map<HashKey, std::vector<Point>, HashKeyHasher> grid;

    VoxelCollisionChecker(float cSize) : cellSize(cSize) {}

    void insert(const Point& p) {
        int i = std::floor(p.x / cellSize);
        int j = std::floor(p.y / cellSize);
        int k = std::floor(p.z / cellSize);
        grid[{i, j, k}].push_back(p);
    }

    bool checkPoint(const Point& p, float radiusSq) const {
        int ci = std::floor(p.x / cellSize);
        int cj = std::floor(p.y / cellSize);
        int ck = std::floor(p.z / cellSize);
        for (int di = -1; di <= 1; ++di) {
            for (int dj = -1; dj <= 1; ++dj) {
                for (int dk = -1; dk <= 1; ++dk) {
                    auto it = grid.find({ci + di, cj + dj, ck + dk});
                    if (it != grid.end()) {
                        for (const auto& op : it->second) {
                            float dx = p.x - op.x;
                            float dy = p.y - op.y;
                            float dz = p.z - op.z;
                            if (dx*dx + dy*dy + dz*dz < radiusSq) return true;
                        }
                    }
                }
            }
        }
        return false;
    }
};

int main() {
    std::cout << "Voxel test OK" << std::endl;
    return 0;
}
