#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <fstream>
#include <unordered_map>
#include <random>

struct Point {
    float x, y, z;
};

struct Quat {
    float w, x, y, z;
};

struct HashKey {
    int i, j, k;
    bool operator==(const HashKey& o) const {
        return i == o.i && j == o.j && k == o.k;
    }
};

struct HashKeyHasher {
    std::size_t operator()(const HashKey& k) const {
        return ((std::hash<int>()(k.i) ^ (std::hash<int>()(k.j) << 1)) >> 1) ^ (std::hash<int>()(k.k) << 1);
    }
};

class VoxelCollisionChecker {
public:
    float cellSize;
    std::unordered_map<HashKey, std::vector<Point>, HashKeyHasher> grid;

    VoxelCollisionChecker(float cSize) : cellSize(cSize) {}

    void insert(const Point& p) {
        int i = std::floor(p.x / cellSize);
        int j = std::floor(p.y / cellSize);
        int k = std::floor(p.z / cellSize);
        grid[{i, j, k}].push_back(p);
    }

    bool checkPoint(const Point& p, float radiusSq) const {
        int ci = std::floor(p.x / cellSize);
        int cj = std::floor(p.y / cellSize);
        int ck = std::floor(p.z / cellSize);
        for (int di = -1; di <= 1; ++di) {
            for (int dj = -1; dj <= 1; ++dj) {
                for (int dk = -1; dk <= 1; ++dk) {
                    auto it = grid.find({ci + di, cj + dj, ck + dk});
                    if (it != grid.end()) {
                        for (const auto& op : it->second) {
                            float dx = p.x - op.x;
                            float dy = p.y - op.y;
                            float dz = p.z - op.z;
                            if (dx*dx + dy*dy + dz*dz < radiusSq) return true;
                        }
                    }
                }
            }
        }
        return false;
    }
};

// Rotate point by quaternion
Point rotatePoint(const Quat& q, const Point& p) {
    // v' = v + 2 * cross(q.xyz, cross(q.xyz, v) + q.w * v)
    float qx = q.x, qy = q.y, qz = q.z, qw = q.w;
    float tx = 2.0f * (qy * p.z - qz * p.y + qw * p.x);
    float ty = 2.0f * (qz * p.x - qx * p.z + qw * p.y);
    float tz = 2.0f * (qx * p.y - qy * p.x + qw * p.z);
    return {
        p.x + qy * tz - qz * ty,
        p.y + qz * tx - qx * tz,
        p.z + qx * ty - qy * tx
    };
}

int main() {
    // Load pts_a
    std::ifstream fa("/app/pts_a.bin", std::ios::binary);
    std::vector<Point> pts_a;
    Point pt;
    while (fa.read(reinterpret_cast<char*>(&pt), sizeof(Point))) {
        pts_a.push_back(pt);
    }
    std::cout << "Loaded pts_a: " << pts_a.size() << std::endl;

    // Load p_local_3k
    std::ifstream fb("/app/p_local_3k.bin", std::ios::binary);
    std::vector<Point> p_local;
    while (fb.read(reinterpret_cast<char*>(&pt), sizeof(Point))) {
        p_local.push_back(pt);
    }
    std::cout << "Loaded p_local_3k: " << p_local.size() << std::endl;

    float collisionRadius = 0.015f; // 1.5 cm safety margin
    float cellSize = 0.02f;
    VoxelCollisionChecker checker(cellSize);
    for (const auto& p : pts_a) {
        checker.insert(p);
    }
    std::cout << "Grid cells: " << checker.grid.size() << std::endl;

    // Test initial pose
    Point pos0 = {1.2f, 0.36f, 0.28f};
    Quat q0 = {1.0f, 0.0f, 0.0f, 0.0f};

    auto checkPose = [&](const Point& pos, const Quat& q) -> bool {
        for (const auto& lp : p_local) {
            Point wp = rotatePoint(q, lp);
            wp.x += pos.x;
            wp.y += pos.y;
            wp.z += pos.z;
            if (checker.checkPoint(wp, collisionRadius * collisionRadius)) {
                return true; // collision
            }
        }
        return false; // free
    };

    bool init_coll = checkPose(pos0, q0);
    std::cout << "Initial pose collision (r=1.5cm): " << (init_coll ? "YES" : "NO (FREE!)") << std::endl;

    // Benchmark 10,000 checks
    auto t0 = std::chrono::high_resolution_clock::now();
    int count = 0;
    for (int i = 0; i < 10000; ++i) {
        Point p = {pos0.x + (i % 10) * 0.001f, pos0.y, pos0.z};
        if (!checkPose(p, q0)) count++;
    }
    auto t1 = std::chrono::high_resolution_clock::now();
    double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
    std::cout << "10,000 checks took: " << ms << " ms (" << ms / 10000.0 << " ms/check)" << std::endl;

    return 0;
}
