#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <fstream>
#include <algorithm>

struct Point {
    float x, y, z;
};

struct Quat {
    float w, x, y, z;
};

// Dense 3D distance grid for tube_a
// Bounds: [-0.25, 2.55] x [-0.25, 1.85] x [-0.35, 0.55]
const float XMIN = -0.25f, XMAX = 2.55f;
const float YMIN = -0.25f, YMAX = 1.85f;
const float ZMIN = -0.35f, ZMAX = 0.55f;
const float RES = 0.01f; // 1 cm resolution
const int NX = (int)std::ceil((XMAX - XMIN) / RES) + 1;
const int NY = (int)std::ceil((YMAX - YMIN) / RES) + 1;
const int NZ = (int)std::ceil((ZMAX - ZMIN) / RES) + 1;

std::vector<float> distGrid(NX * NY * NZ, 1e9f);

inline int getIndex(int i, int j, int k) {
    return (i * NY + j) * NZ + k;
}

Point rotatePoint(const Quat& q, const Point& p) {
    float qx = q.x, qy = q.y, qz = q.z, qw = q.w;
    float tx = 2.0f * (qy * p.z - qz * p.y + qw * p.x);
    float ty = 2.0f * (qz * p.x - qx * p.z + qw * p.y);
    float tz = 2.0f * (qx * p.y - qy * p.x + qw * p.z);
    return {
        p.x + qy * tz - qz * ty,
        p.y + qz * tx - qx * tz,
        p.z + qx * ty - qy * tx
    };
}

int main() {
    std::cout << "Grid dimensions: " << NX << " x " << NY << " x " << NZ 
              << " (" << NX * NY * NZ * sizeof(float) / (1024 * 1024) << " MB)" << std::endl;

    std::ifstream fa("/app/pts_a.bin", std::ios::binary);
    std::vector<Point> pts_a;
    Point pt;
    while (fa.read(reinterpret_cast<char*>(&pt), sizeof(Point))) {
        pts_a.push_back(pt);
    }
    std::cout << "Loaded pts_a: " << pts_a.size() << std::endl;

    // Splat points into grid: for each point in pts_a, update cells within radius 0.05m (5 cells)
    int R_cells = 5;
    for (const auto& p : pts_a) {
        int ci = (int)std::round((p.x - XMIN) / RES);
        int cj = (int)std::round((p.y - YMIN) / RES);
        int ck = (int)std::round((p.z - ZMIN) / RES);
        for (int di = -R_cells; di <= R_cells; ++di) {
            int i = ci + di;
            if (i < 0 || i >= NX) continue;
            float cx = XMIN + i * RES;
            float dx = cx - p.x;
            for (int dj = -R_cells; dj <= R_cells; ++dj) {
                int j = cj + dj;
                if (j < 0 || j >= NY) continue;
                float cy = YMIN + j * RES;
                float dy = cy - p.y;
                float dxy2 = dx*dx + dy*dy;
                for (int dk = -R_cells; dk <= R_cells; ++dk) {
                    int k = ck + dk;
                    if (k < 0 || k >= NZ) continue;
                    float cz = ZMIN + k * RES;
                    float dz = cz - p.z;
                    float d = std::sqrt(dxy2 + dz*dz);
                    int idx = getIndex(i, j, k);
                    if (d < distGrid[idx]) {
                        distGrid[idx] = d;
                    }
                }
            }
        }
    }
    std::cout << "Distance grid populated!" << std::endl;

    std::ifstream fb("/app/p_local_3k.bin", std::ios::binary);
    std::vector<Point> p_local;
    while (fb.read(reinterpret_cast<char*>(&pt), sizeof(Point))) {
        p_local.push_back(pt);
    }
    // Subsample to 500 points
    std::vector<Point> p_local_500;
    for (size_t i = 0; i < p_local.size(); i += 6) {
        p_local_500.push_back(p_local[i]);
    }
    std::cout << "Using " << p_local_500.size() << " test points on tube_b" << std::endl;

    float collisionRadius = 0.015f; // 1.5 cm safety margin
    auto checkPose = [&](const Point& pos, const Quat& q) -> bool {
        for (const auto& lp : p_local_500) {
            Point wp = rotatePoint(q, lp);
            float wx = wp.x + pos.x;
            float wy = wp.y + pos.y;
            float wz = wp.z + pos.z;
            // If outside grid bounds, distance to tube_a is large (> 0.05)
