        }
        int i = (int)((wx - XMIN) / RES);
        int j = (int)((wy - YMIN) / RES);
        int k = (int)((wz - ZMIN) / RES);
        if (distGrid[getIndex(i, j, k)] < collisionRadius) {
            return true;
        }
    }
    return false;
}

