    int N = 64;
    for (int i = 0; i < N; ++i) {
        float y = 1.0f - (i / (float)(N - 1)) * 2.0f;
        float radius = std::sqrt(1.0f - y * y);
        float theta = ((1.0f + std::sqrt(5.0f)) / 2.0f) * i * 3.14159265f * 2.0f;
        float x = std::cos(theta) * radius;
        float z = std::sin(theta) * radius;
        escapeRays.push_back({x, y, z});
    }
}

bool canEscape(const Point& pos, const Quat& q) {
    for (const auto& r : escapeRays) {
        bool blocked = false;
        for (float t = 0.05f; t <= 3.5f; t += 0.08f) {
