const float XMIN = -0.25f, XMAX = 2.55f;
const float YMIN = -0.25f, YMAX = 1.85f;
const float ZMIN = -0.35f, ZMAX = 0.55f;
const float RES = 0.01f;
const int NX = (int)std::ceil((XMAX - XMIN) / RES) + 1;
const int NY = (int)std::ceil((YMAX - YMIN) / RES) + 1;
const int NZ = (int)std::ceil((ZMAX - ZMIN) / RES) + 1;

std::vector<float> distGrid(NX * NY * NZ, 1e9f);

inline int getIndex(int i, int j, int k) {
    return (i * NY + j) * NZ + k;
}

Point rotatePoint(const Quat& q, const Point& p) {
    float qx = q.x, qy = q.y, qz = q.z, qw = q.w;
    float tx = 2.0f * (qy * p.z - qz * p.y + qw * p.x);
    float ty = 2.0f * (qz * p.x - qx * p.z + qw * p.y);
    float tz = 2.0f * (qx * p.y - qy * p.x + qw * p.z);
    return {
        p.x + qy * tz - qz * ty,
        p.y + qz * tx - qx * tz,
        p.z + qx * ty - qy * tx
    };
}

Quat slerp(const Quat& q1, const Quat& q2, float t) {
    float dot = q1.w * q2.w + q1.x * q2.x + q1.y * q2.y + q1.z * q2.z;
    Quat target = q2;
    if (dot < 0.0f) {
        dot = -dot;
        target = {-q2.w, -q2.x, -q2.y, -q2.z};
    }
    if (dot > 0.9995f) {
        Quat res = {
            q1.w + t * (target.w - q1.w),
            q1.x + t * (target.x - q1.x),
            q1.y + t * (target.y - q1.y),
            q1.z + t * (target.z - q1.z)
        };
        float l = std::sqrt(res.w*res.w + res.x*res.x + res.y*res.y + res.z*res.z);
        return {res.w/l, res.x/l, res.y/l, res.z/l};
    }
    float theta_0 = std::acos(dot);
    float theta = theta_0 * t;
    float sin_theta = std::sin(theta);
    float sin_theta_0 = std::sin(theta_0);
    float s0 = std::cos(theta) - dot * sin_theta / sin_theta_0;
    float s1 = sin_theta / sin_theta_0;
    return {
        s0 * q1.w + s1 * target.w,
        s0 * q1.x + s1 * target.x,
        s0 * q1.y + s1 * target.y,
        s0 * q1.z + s1 * target.z
    };
}

std::vector<Point> p_local_test;
float collisionRadius = 0.020f; // 2.0 cm safety margin

bool checkPose(const Point& pos, const Quat& q) {
    for (const auto& lp : p_local_test) {
        Point wp = rotatePoint(q, lp);
        float wx = wp.x + pos.x;
        float wy = wp.y + pos.y;
        float wz = wp.z + pos.z;
        if (wx < XMIN || wx >= XMAX || wy < YMIN || wy >= YMAX || wz < ZMIN || wz >= ZMAX) {
            continue;
        }
        int i = (int)((wx - XMIN) / RES);
        int j = (int)((wy - YMIN) / RES);
        int k = (int)((wz - ZMIN) / RES);
        if (distGrid[getIndex(i, j, k)] < collisionRadius) {
            return true;
        }
    }
    return false;
}

std::vector<Point> escapeRays;
void initRays() {
    int N = 64;
    for (int i = 0; i < N; ++i) {
        float y = 1.0f - (i / (float)(N - 1)) * 2.0f;
        float radius = std::sqrt(1.0f - y * y);
        float theta = ((1.0f + std::sqrt(5.0f)) / 2.0f) * i * 3.14159265f * 2.0f;
        float x = std::cos(theta) * radius;
        float z = std::sin(theta) * radius;
        escapeRays.push_back({x, y, z});
    }
}

bool canEscape(const Point& pos, const Quat& q) {
    for (const auto& r : escapeRays) {
        bool blocked = false;
        for (float t = 0.05f; t <= 3.5f; t += 0.08f) {
            Point p = {pos.x + t * r.x, pos.y + t * r.y, pos.z + t * r.z};
            if (checkPose(p, q)) {
                blocked = true;
                break;
            }
        }
        if (!blocked) return true;
    }
    return false;
}

struct Node {
    Point pos;
    Quat q;
    int parent;
};

inline float distanceMetric(const Node& a, const Point& p, const Quat& q) {
    float dx = a.pos.x - p.x;
    float dy = a.pos.y - p.y;
    float dz = a.pos.z - p.z;
    float dpos2 = dx*dx + dy*dy + dz*dz;
    float dot = std::abs(a.q.w * q.w + a.q.x * q.x + a.q.y * q.y + a.q.z * q.z);
    float drot = 1.0f - std::min(1.0f, dot);
    return dpos2 + 0.5f * drot;
}

