    if (argc > 1) {
        collisionRadius = std::atof(argv[1]);
    }
    std::cout << "Using collisionRadius = " << collisionRadius << " m" << std::endl;

    std::ifstream fa("/app/pts_a.bin", std::ios::binary);
    std::vector<Point> pts_a;
    Point pt;
    while (fa.read(reinterpret_cast<char*>(&pt), sizeof(Point))) pts_a.push_back(pt);

    int R_cells = 5;
    for (const auto& p : pts_a) {
        int ci = (int)std::round((p.x - XMIN) / RES);
        int cj = (int)std::round((p.y - YMIN) / RES);
        int ck = (int)std::round((p.z - ZMIN) / RES);
        for (int di = -R_cells; di <= R_cells; ++di) {
            int i = ci + di;
            if (i < 0 || i >= NX) continue;
            float dx = (XMIN + i * RES) - p.x;
            for (int dj = -R_cells; dj <= R_cells; ++dj) {
                int j = cj + dj;
                if (j < 0 || j >= NY) continue;
                float dy = (YMIN + j * RES) - p.y;
                float dxy2 = dx*dx + dy*dy;
                for (int dk = -R_cells; dk <= R_cells; ++dk) {
                    int k = ck + dk;
                    if (k < 0 || k >= NZ) continue;
                    float dz = (ZMIN + k * RES) - p.z;
                    float d = std::sqrt(dxy2 + dz*dz);
                    int idx = getIndex(i, j, k);
                    if (d < distGrid[idx]) distGrid[idx] = d;
                }
            }
        }
    }

