    while (fb.read(reinterpret_cast<char*>(&pt), sizeof(Point))) p_local.push_back(pt);
    // Use 1500 points
    for (size_t i = 0; i < p_local.size(); i += 2) p_local_test.push_back(p_local[i]);
    std::cout << "Test points count: " << p_local_test.size() << std::endl;

    initRays();

    Point pos0 = {1.2f, 0.36f, 0.28f};
    Quat q0 = {1.0f, 0.0f, 0.0f, 0.0f};

    if (checkPose(pos0, q0)) {
        std::cerr << "ERROR: Initial pose is in collision with radius " << collisionRadius << std::endl;
        return 1;
    }
    std::cout << "Initial pose is clean!" << std::endl;

    std::vector<Node> tree;
    tree.reserve(150000);
    tree.push_back({pos0, q0, -1});

    std::mt19937 rng(1337);
    std::uniform_real_distribution<float> rand_x(0.2f, 2.2f);
    std::uniform_real_distribution<float> rand_y(-0.4f, 2.0f);
    std::uniform_real_distribution<float> rand_z(-0.3f, 0.9f);
    std::normal_distribution<float> norm_dist(0.0f, 1.0f);

    std::cout << "Starting RRT planner..." << std::endl;
