        Quat q_rand = {norm_dist(rng), norm_dist(rng), norm_dist(rng), norm_dist(rng)};
        float lq = std::sqrt(q_rand.w*q_rand.w + q_rand.x*q_rand.x + q_rand.y*q_rand.y + q_rand.z*q_rand.z);
        q_rand = {q_rand.w/lq, q_rand.x/lq, q_rand.y/lq, q_rand.z/lq};

        int nearest_idx = 0;
        float min_dist = distanceMetric(tree[0], p_rand, q_rand);
        int step_stride = std::max(1, (int)tree.size() / 3000);
        for (size_t i = 0; i < tree.size(); i += step_stride) {
            float d = distanceMetric(tree[i], p_rand, q_rand);
            if (d < min_dist) {
                min_dist = d;
                nearest_idx = i;
            }
        }

        const auto& near_node = tree[nearest_idx];
        float dx = p_rand.x - near_node.pos.x;
        float dy = p_rand.y - near_node.pos.y;
        float dz = p_rand.z - near_node.pos.z;
        float dist_pos = std::sqrt(dx*dx + dy*dy + dz*dz);
        float dot = std::abs(near_node.q.w * q_rand.w + near_node.q.x * q_rand.x + near_node.q.y * q_rand.y + near_node.q.z * q_rand.z);
        float dist_rot = std::acos(std::min(1.0f, dot)) * 2.0f;

        int num_steps = std::min(12, (int)std::max(dist_pos / step_size_pos, dist_rot / step_size_rot));
        if (num_steps < 1) num_steps = 1;

        int prev_idx = nearest_idx;
        for (int step = 1; step <= num_steps; ++step) {
            float frac = (float)step / num_steps;
            Point next_p = {
                near_node.pos.x + frac * dx,
                near_node.pos.y + frac * dy,
                near_node.pos.z + frac * dz
            };
            Quat next_q = slerp(near_node.q, q_rand, frac);

            if (checkPose(next_p, next_q)) {
                break;
            }

            tree.push_back({next_p, next_q, prev_idx});
            prev_idx = tree.size() - 1;

            if (canEscape(next_p, next_q)) {
                winning_idx = tree.size() - 1;
                std::cout << "FOUND ESCAPE AT NODE " << winning_idx << " (iter " << iter << ")!" << std::endl;
                break;
            }
        }

        if (winning_idx != -1) break;

        if (iter % 5000 == 0 && iter > 0) {
            auto t_now = std::chrono::high_resolution_clock::now();
            double s = std::chrono::duration<double>(t_now - t0).count();
            std::cout << "Iter " << iter << ", tree size: " << tree.size() 
                      << ", elapsed: " << s << "s"
                      << std::endl;
        }
    }

    if (winning_idx != -1) {
        std::vector<int> path;
        int curr = winning_idx;
        while (curr != -1) {
            path.push_back(curr);
            curr = tree[curr].parent;
        }
        std::reverse(path.begin(), path.end());
        std::cout << "Winning path length: " << path.size() << " steps!" << std::endl;

        std::ofstream out("/app/rrt_robust_path.txt");
        for (int idx : path) {
            out << std::setprecision(6) << tree[idx].pos.x << " " << tree[idx].pos.y << " " << tree[idx].pos.z << " "
                << tree[idx].q.w << " " << tree[idx].q.x << " " << tree[idx].q.y << " " << tree[idx].q.z << "\n";
        }
        out.close();
    } else {
        std::cout << "Did not find escape in " << tree.size() << " nodes." << std::endl;
    }

    return 0;
}
