const float YMIN = -0.25f, YMAX = 1.85f;
const float ZMIN = -0.35f, ZMAX = 0.55f;
const float RES = 0.01f;
const int NX = (int)std::ceil((XMAX - XMIN) / RES) + 1;
const int NY = (int)std::ceil((YMAX - YMIN) / RES) + 1;
const int NZ = (int)std::ceil((ZMAX - ZMIN) / RES) + 1;

std::vector<float> distGrid(NX * NY * NZ, 1e9f);

inline int getIndex(int i, int j, int k) {
    return (i * NY + j) * NZ + k;
}

Point rotatePoint(const Quat& q, const Point& p) {
    float qx = q.x, qy = q.y, qz = q.z, qw = q.w;
    float tx = 2.0f * (qy * p.z - qz * p.y + qw * p.x);
    float ty = 2.0f * (qz * p.x - qx * p.z + qw * p.y);
    float tz = 2.0f * (qx * p.y - qy * p.x + qw * p.z);
    return {
        p.x + qy * tz - qz * ty,
        p.y + qz * tx - qx * tz,
        p.z + qx * ty - qy * tx
    };
}

Quat slerp(const Quat& q1, const Quat& q2, float t) {
    float dot = q1.w * q2.w + q1.x * q2.x + q1.y * q2.y + q1.z * q2.z;
    Quat target = q2;
    if (dot < 0.0f) {
        dot = -dot;
        target = {-q2.w, -q2.x, -q2.y, -q2.z};
    }
    if (dot > 0.9995f) {
        Quat res = {
            q1.w + t * (target.w - q1.w),
            q1.x + t * (target.x - q1.x),
            q1.y + t * (target.y - q1.y),
            q1.z + t * (target.z - q1.z)
        };
        float l = std::sqrt(res.w*res.w + res.x*res.x + res.y*res.y + res.z*res.z);
        return {res.w/l, res.x/l, res.y/l, res.z/l};
    }
    float theta_0 = std::acos(dot);
    float theta = theta_0 * t;
    float sin_theta = std::sin(theta);
    float sin_theta_0 = std::sin(theta_0);
    float s0 = std::cos(theta) - dot * sin_theta / sin_theta_0;
    float s1 = sin_theta / sin_theta_0;
    return {
        s0 * q1.w + s1 * target.w,
        s0 * q1.x + s1 * target.x,
        s0 * q1.y + s1 * target.y,
        s0 * q1.z + s1 * target.z
    };
}

Quat quatMultiply(const Quat& q1, const Quat& q2) {
    return {
        q1.w * q2.w - q1.x * q2.x - q1.y * q2.y - q1.z * q2.z,
        q1.w * q2.x + q1.x * q2.w + q1.y * q2.z - q1.z * q2.y,
        q1.w * q2.y - q1.x * q2.z + q1.y * q2.w + q1.z * q2.x,
        q1.w * q2.z + q1.x * q2.y - q1.y * q2.x + q1.z * q2.w
    };
}

Quat quatFromRotVec(float rx, float ry, float rz) {
    float theta = std::sqrt(rx * rx + ry * ry + rz * rz);
    if (theta < 1e-6f) return {1.0f, 0.0f, 0.0f, 0.0f};
    float half = 0.5f * theta;
    float s = std::sin(half) / theta;
    return {std::cos(half), rx * s, ry * s, rz * s};
}

