Quat slerp(const Quat& q1, const Quat& q2, float t) {
    float dot = q1.w * q2.w + q1.x * q2.x + q1.y * q2.y + q1.z * q2.z;
    Quat target = q2;
    if (dot < 0.0f) {
        dot = -dot;
        target = {-q2.w, -q2.x, -q2.y, -q2.z};
