    float theta = theta_0 * t;
    float sin_theta = std::sin(theta);
    float sin_theta_0 = std::sin(theta_0);
    float s0 = std::cos(theta) - dot * sin_theta / sin_theta_0;
    float s1 = sin_theta / sin_theta_0;
    return {
        s0 * q1.w + s1 * target.w,
        s0 * q1.x + s1 * target.x,
        s0 * q1.y + s1 * target.y,
        s0 * q1.z + s1 * target.z
    };
}

