    std::uniform_real_distribution<float> rand_y(0.8f, 2.5f);
    std::uniform_real_distribution<float> rand_z(0.3f, 1.0f);
    std::normal_distribution<float> norm_dist(0.0f, 1.0f);

    int winning_idx = -1;
    const float step_size_pos = 0.02f;
