        float dy = p_rand.y - near_node.pos.y;
        float dz = p_rand.z - near_node.pos.z;
        float dist_pos = std::sqrt(dx*dx + dy*dy + dz*dz);
        float dot = std::abs(near_node.q.w * q_rand.w + near_node.q.x * q_rand.x + near_node.q.y * q_rand.y + near_node.q.z * q_rand.z);
        float dist_rot = std::acos(std::min(1.0f, dot)) * 2.0f;

        int num_steps = std::min(8, (int)std::max(dist_pos / step_size_pos, dist_rot / step_size_rot));
        if (num_steps < 1) num_steps = 1;

