            }
        }

        if (winning_idx != -1) break;
    }

    if (winning_idx != -1) {
        std::vector<int> path;
        int curr = winning_idx;
        while (curr != -1) {
            path.push_back(curr);
            curr = tree[curr].parent;
        }
        std::reverse(path.begin(), path.end());
        std::cout << "Winning path length: " << path.size() << " steps!" << std::endl;

        std::ofstream out("/app/final_escape_path.txt");
        for (int idx : path) {
            out << std::setprecision(6) << tree[idx].pos.x << " " << tree[idx].pos.y << " " << tree[idx].pos.z << " "
                << tree[idx].q.w << " " << tree[idx].q.x << " " << tree[idx].q.y << " " << tree[idx].q.z << "\n";
        }
        out.close();
    } else {
        std::cout << "Did not find escape in " << tree.size() << " nodes." << std::endl;
    }

    return 0;
}
