    float tz = 2.0f * (qx * p.y - qy * p.x + qw * p.z);
    return {
        p.x + qy * tz - qz * ty,
        p.y + qz * tx - qx * tz,
        p.z + qx * ty - qy * tx
    };
}

Quat slerp(const Quat& q1, const Quat& q2, float t) {
    float dot = q1.w * q2.w + q1.x * q2.x + q1.y * q2.y + q1.z * q2.z;
    Quat target = q2;
    if (dot < 0.0f) {
        dot = -dot;
        target = {-q2.w, -q2.x, -q2.y, -q2.z};
    }
    if (dot > 0.9995f) {
        Quat res = {
            q1.w + t * (target.w - q1.w),
            q1.x + t * (target.x - q1.x),
            q1.y + t * (target.y - q1.y),
            q1.z + t * (target.z - q1.z)
        };
        float l = std::sqrt(res.w*res.w + res.x*res.x + res.y*res.y + res.z*res.z);
        return {res.w/l, res.x/l, res.y/l, res.z/l};
    }
    float theta_0 = std::acos(dot);
    float theta = theta_0 * t;
    float sin_theta = std::sin(theta);
    float sin_theta_0 = std::sin(theta_0);
    float s0 = std::cos(theta) - dot * sin_theta / sin_theta_0;
    float s1 = sin_theta / sin_theta_0;
    return {
        s0 * q1.w + s1 * target.w,
        s0 * q1.x + s1 * target.x,
        s0 * q1.y + s1 * target.y,
        s0 * q1.z + s1 * target.z
    };
