        float c = getClearance(cand_p, cand_q);
        if (c > best_c) {
            best_c = c;
            best_p = cand_p;
            best_q = cand_q;
            if (canEscape(cand_p, cand_q)) {
                std::cout << "FOUND ESCAPE CANDIDATE at iter " << it << ": clearance = " << c * 1000.0f << " mm" << std::endl;
                std::cout << "Pos: [" << cand_p.x << ", " << cand_p.y << ", " << cand_p.z << "]" << std::endl;
                std::cout << "Quat: [" << cand_q.w << ", " << cand_q.x << ", " << cand_q.y << ", " << cand_q.z << "]" << std::endl;

                std::ofstream out("/app/direct_escape.txt");
                out << std::setprecision(6) << cand_p.x << " " << cand_p.y << " " << cand_p.z << " "
                    << cand_q.w << " " << cand_q.x << " " << cand_q.y << " " << cand_q.z << "\n";
                out.close();
                break;
            }
        }
    }

    std::cout << "Best clearance found: " << best_c * 1000.0f << " mm" << std::endl;
    return 0;
}
