#include <iostream>
#include <vector>
#include <cmath>
#include <fstream>

struct Point { float x, y, z; };
struct Quat { float w, x, y, z; };

const float XMIN = -0.25f, XMAX = 2.55f;
const float YMIN = -0.25f, YMAX = 1.85f;
const float ZMIN = -0.35f, ZMAX = 0.55f;
const float RES = 0.01f;
const int NX = (int)std::ceil((XMAX - XMIN) / RES) + 1;
const int NY = (int)std::ceil((YMAX - YMIN) / RES) + 1;
const int NZ = (int)std::ceil((ZMAX - ZMIN) / RES) + 1;

std::vector<float> distGrid(NX * NY * NZ, 1e9f);

inline int getIndex(int i, int j, int k) {
    return (i * NY + j) * NZ + k;
}

Point rotatePoint(const Quat& q, const Point& p) {
    float qx = q.x, qy = q.y, qz = q.z, qw = q.w;
    float tx = 2.0f * (qy * p.z - qz * p.y + qw * p.x);
    float ty = 2.0f * (qz * p.x - qx * p.z + qw * p.y);
    float tz = 2.0f * (qx * p.y - qy * p.x + qw * p.z);
    return {
        p.x + qy * tz - qz * ty,
        p.y + qz * tx - qx * tz,
        p.z + qx * ty - qy * tx
    };
}

std::vector<Point> p_local_all;

float getClearance(const Point& pos, const Quat& q) {
    float min_d = 1e9f;
    for (const auto& lp : p_local_all) {
        Point wp = rotatePoint(q, lp);
        float wx = wp.x + pos.x;
        float wy = wp.y + pos.y;
        float wz = wp.z + pos.z;
        if (wx < XMIN || wx >= XMAX || wy < YMIN || wy >= YMAX || wz < ZMIN || wz >= ZMAX) continue;
        int i = (int)((wx - XMIN) / RES);
        int j = (int)((wy - YMIN) / RES);
        int k = (int)((wz - ZMIN) / RES);
        float d = distGrid[getIndex(i, j, k)];
        if (d < min_d) min_d = d;
    }
    return min_d;
}

int main() {
    std::ifstream fa("/app/pts_a.bin", std::ios::binary);
    std::vector<Point> pts_a;
    Point pt;
    while (fa.read(reinterpret_cast<char*>(&pt), sizeof(Point))) pts_a.push_back(pt);

    int R_cells = 5;
    for (const auto& p : pts_a) {
        int ci = (int)std::round((p.x - XMIN) / RES);
        int cj = (int)std::round((p.y - YMIN) / RES);
        int ck = (int)std::round((p.z - ZMIN) / RES);
        for (int di = -R_cells; di <= R_cells; ++di) {
            int i = ci + di;
            if (i < 0 || i >= NX) continue;
            float dx = (XMIN + i * RES) - p.x;
            for (int dj = -R_cells; dj <= R_cells; ++dj) {
                int j = cj + dj;
                if (j < 0 || j >= NY) continue;
                float dy = (YMIN + j * RES) - p.y;
                float dxy2 = dx*dx + dy*dy;
                for (int dk = -R_cells; dk <= R_cells; ++dk) {
                    int k = ck + dk;
                    if (k < 0 || k >= NZ) continue;
                    float dz = (ZMIN + k * RES) - p.z;
                    float d = std::sqrt(dxy2 + dz*dz);
                    int idx = getIndex(i, j, k);
                    if (d < distGrid[idx]) distGrid[idx] = d;
                }
            }
        }
    }

    std::ifstream fb("/app/p_local_3k.bin", std::ios::binary);
    while (fb.read(reinterpret_cast<char*>(&pt), sizeof(Point))) p_local_all.push_back(pt);

    Point pos_esc = {1.22604f, 1.82783f, 0.739997f};
    Quat q_esc = {0.389063f, -0.739228f, -0.526219f, 0.158949f};

    std::cout << "Clearance at escape pose: " << getClearance(pos_esc, q_esc) * 1000.0f << " mm" << std::endl;

    int N = 256;
    int freeRays = 0;
    std::vector<Point> freeDirs;
    for (int i = 0; i < N; ++i) {
        float y = 1.0f - (i / (float)(N - 1)) * 2.0f;
        float radius = std::sqrt(1.0f - y * y);
        float theta = ((1.0f + std::sqrt(5.0f)) / 2.0f) * i * 3.14159265f * 2.0f;
        float rx = std::cos(theta) * radius;
        float rz = std::sin(theta) * radius;
        float ry = y;

        bool blocked = false;
        for (float t = 0.05f; t <= 3.5f; t += 0.05f) {
            Point p = {pos_esc.x + t * rx, pos_esc.y + t * ry, pos_esc.z + t * rz};
            if (getClearance(p, q_esc) < 0.010f) {
                blocked = true;
                break;
            }
        }
        if (!blocked) {
            freeRays++;
            freeDirs.push_back({rx, ry, rz});
        }
    }
    std::cout << "Free escape rays from escape pose: " << freeRays << " / " << N << std::endl;
    if (freeRays > 0) {
        std::cout << "First free ray: [" << freeDirs[0].x << ", " << freeDirs[0].y << ", " << freeDirs[0].z << "]" << std::endl;
    }

    return 0;
}
